source('mp10_hypothesis_followup_v1/scripts/common.R');suppressPackageStartupMessages(library(edgeR))
res<-rd('model_results.tsv.gz');mem<-rd('model_membership.tsv.gz');b<-qread(file.path(OLD,'objects/pseudobulk.qs'),nthreads=1);t<-qread(file.path(B,'objects/treg_strata.qs'),nthreads=1);dir.create(file.path(B,'tables/treg_de'),showWarnings=FALSE)
# The pre-registered decomposition models define samples, covariates and exposure scales.
ids<-res[grepl('^treg_decomposition',FDR_family)&y=='OXIDATIVE_PHOSPHORYLATION_Full'& (setting%in%c('main','min30','replace_b','Q95')|grepl('^LODO_',setting))]
# exact All-Treg controls for each NC sample cohort use the pre-registered MP10 matched row.
ids<-rbind(ids,res[grepl('^bridge_matched_all',FDR_family)&x%in%c('MP10_Q50','MP10_Q95')&(setting%in%c('main','min30','replace_b','Q95')|grepl('^LODO_',setting))],fill=TRUE)
all<-list();status<-list();ox<-fread(file.path(REF,'hallmark.tsv.gz'))[gs_name=='HALLMARK_OXIDATIVE_PHOSPHORYLATION',unique(gene_symbol)]
for(i in seq_len(nrow(ids))){r<-ids[i];m<-mem[model_id==r$model_id];if(r$n_specimens<4||!is.finite(r$residual_df)||r$residual_df<3){status[[i]]<-r[,.(model_id,status,reason,n_specimens,residual_df)];next};m[,profile_id:=paste(sample_uid,celltype,sep='|')];X<-model.matrix(if(uniqueN(m$dataset)>1)~dataset+x else ~x,m);ct<-if(r$celltype%in%c('Treg_NC','Treg_CY'))t$counts else b$counts;cts<-ct[,m$profile_id,drop=FALSE];sig<-digest(list(cts,m,X,'edgeR4.8.2 filterByExpr TMM robustQL'),algo='sha256');f<-file.path(B,'tables/treg_de',paste0(r$model_id,'.tsv.gz'))
 if(file.exists(f)&&file.exists(paste0(f,'.sha256'))&&readLines(paste0(f,'.sha256'))==sig)tt<-fread(f)else{
  y<-DGEList(cts);keep<-filterByExpr(y,X);y<-calcNormFactors(y[keep,,keep.lib.sizes=FALSE]);y<-estimateDisp(y,X,robust=TRUE);fit<-glmQLFit(y,X,robust=TRUE);tt<-as.data.table(topTags(glmQLFTest(fit,coef='x'),n=Inf,sort.by='none')$table,keep.rownames='gene');tt[,`:=`(model_id=r$model_id,celltype=r$celltype,setting=r$setting,cohort=r$cohort,n_specimens=r$n_specimens,n_datasets=r$n_datasets,residual_df=r$residual_df)];fwrite(tt,f,sep='\t',compress='gzip');writeLines(sig,paste0(f,'.sha256'))
 };tt[,OXPHOS_member:=gene%in%ox];cg<-rd('respiratory_complex_gene_registry.tsv');tt[,respiratory_component:=cg$respiratory_component[match(gene,cg$gene)]];tt[is.na(respiratory_component),respiratory_component:='other'];tt[,genome:=ifelse(grepl('^MT-',gene),'mitochondrial','nuclear')];all[[i]]<-tt[OXPHOS_member|respiratory_component!='other'];status[[i]]<-r[,.(model_id,status='completed',reason='edgeR estimable independently of HC3 score covariance',n_specimens,residual_df)];cat('GENE',i,nrow(ids),r$model_id,'\n');put(rbindlist(status,fill=TRUE),'treg_gene_model_status.tsv')
}
z<-rbindlist(all,fill=TRUE);put(z,'treg_OXPHOS_gene_results.tsv.gz');put(z[,.(n_genes=.N,n_positive=sum(logFC>0),n_negative=sum(logFC<0),median_logFC=median(logFC),n_FDR05=sum(FDR<.05)),by=.(model_id,celltype,setting,cohort,respiratory_component,genome)],'respiratory_component_summary.tsv');cat('TREG GENE MODELS COMPLETE\n')
